describe('Logo Navigation to Home Page', () => {
  beforeEach(() => {
    cy.visit('/dashboard');
  });

  it('should navigate to home page when logo is clicked', () => {
    // Verify we are on the dashboard page
    cy.get('[data-testid="page-title"]').should('contain', 'Dashboard');

    // Verify logo exists
    cy.get('[data-testid="logo"]').should('be.visible');

    // Click the logo
    cy.get('[data-testid="logo"]').click();

    // Verify navigation to home page
    cy.url().should('include', '/');
    cy.get('[data-testid="page-title"]').should('contain', 'Home');
    cy.get('[data-testid="home-hero"]').should('be.visible');
  });

  it('should handle logo click when on home page and navigate to home page', () => {
    // Navigate to home page first
    cy.visit('/');
    cy.get('[data-testid="page-title"]').should('contain', 'Home');

    // Click the logo on home page
    cy.get('[data-testid="logo"]').click();

    // Verify we are still on home page
    cy.url().should('include', '/');
    cy.get('[data-testid="page-title"]').should('contain', 'Home');
    cy.get('[data-testid="home-hero"]').should('be.visible');
  });
});
